// Solder Eave Weather Station Enclosure - Procedural OpenSCAD
$fn = 36;
wall = 2.0;
inner_x = 122.0;
inner_y = 88.0;
inner_z = 34.0;
outer_x = inner_x + 2*wall;
outer_y = inner_y + 2*wall;
outer_z = inner_z + 2*wall;

module eave_housing() {
  difference() {
    cube([outer_x, outer_y, outer_z]);
    translate([wall, wall, wall])
      cube([inner_x, inner_y, inner_z + 1]);
    // HC-SR04 ultrasonic transducer twin ports
    translate([outer_x - wall - 1, 22, wall + 10])
      rotate([0, 90, 0]) cylinder(r = 8.1, h = wall + 2);
    translate([outer_x - wall - 1, 48, wall + 10])
      rotate([0, 90, 0]) cylinder(r = 8.1, h = wall + 2);
    // Slanted weather baffle vents for DHT11
    for (i = [0:4]) {
      translate([-1, 30 + (i*6), wall + 5])
        cube([wall + 2, 3, 10]);
    }
  }
}

module eave_lid() {
  difference() {
    cube([outer_x, outer_y, wall + 2]);
    // Diagnostic OLED window
    translate([wall + 40, wall + 40, -1])
      cube([27, 17, wall + 4]);
    // Solar cable gland notch
    translate([outer_x/2 - 5, -1, wall])
      cube([10, wall + 2, 3]);
  }
}

eave_housing();
translate([0, outer_y + 12, 0]) eave_lid();

