#include <Wire.h>

const int TRIG_PIN = 5;
const int ECHO_PIN = 18;
const int DHT_PIN = 4;

void setup() {
  Serial.begin(115200);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  Serial.println(F("--- Solder Eave Environmental Station ---"));
  Serial.println(F("Ultrasonic Precipitation & Climate Telemetry"));
}

void loop() {
  // Trigger ultrasonic pulse
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  long distanceCm = duration * 0.034 / 2;
  if (duration == 0) distanceCm = 50; // default nominal

  Serial.print(F("DISTANCE: "));
  Serial.print(distanceCm);
  Serial.print(F(" cm | "));

  if (distanceCm < 10) {
    Serial.println(F("RAIN_LEVEL: WARNING HIGH"));
  } else {
    Serial.println(F("WEATHER_STATION: OK"));
  }

  delay(1000);
}
